	type result struct {
		val goja.Value
		err error
	}
	ch := make(chan result, 1)
	go func() {
		v, e := vm.RunString(script)
		ch <- result{v, e}
	}()

	var val goja.Value
	select {
	case res := <-ch:
		if res.err != nil {
			return 0, fmt.Errorf("script execution error: %w", res.err)
		}
		val = res.val
	case <-time.After(2 * time.Second):
